var stock = new Dictionary<string, int> { ["pen"] = 10, ["ink"] = 3 };
var out_ = Solution.ApplySales(stock, new[] { ("pen", 4), ("ink", 3) });
Cj.Eq(out_["pen"], 6, "pen sold");
Cj.Eq(out_["ink"], 0, "ink to exactly zero is fine");
Cj.True(ReferenceEquals(stock, out_), "same instance mutated");

var stock = new Dictionary<string, int> { ["pen"] = 2 };
bool t1 = false, t2 = false;
try { Solution.ApplySales(stock, new[] { ("pen", 3) }); } catch (InvalidOperationException) { t1 = true; }
try { Solution.ApplySales(stock, new[] { ("ghost", 1) }); } catch (InvalidOperationException) { t2 = true; }
Cj.True(t1 && t2, "negative and unknown both throw");
Cj.Eq(stock["pen"], 2, "failed sale leaves stock untouched");
